INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (1, 'BMI（体质指数）', E'BMI = 体重(kg) ÷ 身高(m)²。用于评估体重是否在健康范围。\n\n中国标准：\n- < 18.5：偏瘦\n- 18.5 ~ 23.9：正常\n- 24 ~ 27.9：超重\n- ≥ 28：肥胖', '名词解释', t, 1);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (2, 'BMR（基础代谢率）', E'基础代谢率是指人体在清醒且极端安静状态下，维持生命所需的最低能量。\n\n计算公式（Mifflin-St Jeor）：\n男：BMR = 10×体重(kg) + 6.25×身高(cm) - 5×年龄 + 5\n女：BMR = 10×体重(kg) + 6.25×身高(cm) - 5×年龄 - 161', '计算公式', t, 2);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (3, '每天摄入总能量', E'每天应该吃多少热量，由标准体重、能量系数、年龄系数共同决定。\n\n计算公式：每天摄入总能量 = 标准体重 × 能量系数 × 年龄系数\n\n标准体重 = 身高(cm) - 105\n\n能量系数：根据体力活动确定\n- 卧床：25 kcal/kg/天\n- 轻体力（坐办公室）：30 kcal/kg/天\n- 中体力（走动较多）：35 kcal/kg/天\n- 重体力（体力劳动）：40 kcal/kg/天\n\n年龄系数：根据年龄确定\n- 50岁以下：1.0\n- 50-59岁：0.9\n- 60-69岁：0.8\n- 70-79岁：0.7\n- 80岁以上：0.6\n\n特殊规则：当BMI ≥ 28时，用调节体重替代标准体重\n调节体重 = (真实体重 + 标准体重) ÷ 2', '计算公式', t, 3);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (4, '什么是低碳水饮食', E'低碳水饮食（Low-Carb Diet）是一种减少碳水化合物摄入、增加脂肪和适量蛋白质的饮食方式。\n\n核心原理：减少碳水摄入 → 降低胰岛素水平 → 促进脂肪分解供能。\n\n注意：不是零碳水，而是控制质量和数量。优先选择粗粮、蔬菜中的优质碳水。', '名词解释', t, 4);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (5, '三大营养素能量换算', E'1克蛋白质 = 4 kcal\n1克碳水化合物 = 4 kcal\n1克脂肪 = 9 kcal\n\n每天的总热量摄入由这三类营养素提供，比例不同决定了饮食的性质。', '计算公式', t, 5);

