INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (6, '蛋白质的作用', E'蛋白质是人体的"建材"——构成肌肉、皮肤、毛发、酶和激素。\n\n低碳水饮食期间，蛋白质摄入要充足，防止肌肉流失。\n\n推荐来源：鸡胸肉、鱼虾、鸡蛋、豆腐、瘦肉。', '名词解释', f, 6);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (7, '脂肪的作用与误区', E'脂肪不是坏东西！它是人体的重要能量储备，也是细胞膜的重要组成部分。\n\n低碳水饮食中脂肪是主要能量来源。\n\n推荐来源：橄榄油、牛油果、坚果、深海鱼。\n\n⚠️ 注意：要避免反式脂肪酸（氢化植物油）。', '名词解释', f, 7);

INSERT INTO knowledge_base (id, title, content, category, is_displayed, display_order) VALUES (8, '生酮饮食的注意事项', E'生酮饮食（Ketogenic Diet）是极低碳水（5%）、高脂肪（70%）、适量蛋白质（25%）的饮食方式。\n\n⚠️ 需在专业指导下进行，不适合：\n- 糖尿病患者\n- 肝胆疾病患者\n- 孕妇和哺乳期\n- 60岁以上老年人\n\n初期可能出现"生酮流感"（头晕、乏力），通常1-2周消失。', '名词解释', f, 8);

